INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('30ad22b1-a478-4dd7-8028-c3aa07699d97', 'contactos.descricao', '{"pt":"Fale com a Galeria Contagiarte por WhatsApp, email ou telefone.","en":"Reach Galeria Contagiarte on WhatsApp, by email or by phone.","es":"Contacte con la Galería Contagiarte por WhatsApp, email o teléfono."}', 'Descrição da página nos motores de busca e nos cartões de partilha.', 'contactos', 1790244774);
