INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('72ccd1fc-b008-47de-a8e9-a189e61e92a5', 'contactos.intro', '{"pt":"O WhatsApp é o caminho mais rápido. Respondemos todos os dias.","en":"WhatsApp is the fastest route. We answer every day.","es":"WhatsApp es la vía más rápida. Respondemos todos los días."}', 'Frase de abertura, ao lado dos contactos.', 'contactos', 1790244774);
