INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('c4710d61-1513-41e0-9787-1e5d5998d72d', 'contactos.whatsapp.visita', '{"pt":"Olá, queria marcar uma visita à galeria.","en":"Hello, I would like to book a visit to the gallery.","es":"Hola, quería concertar una visita a la galería."}', 'Mensagem já escrita no botão de marcar visita.', 'contactos', 1790244774);
