INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('fc528322-b0ab-459e-9f68-f73cfd499af7', 'whatsapp.site', '{"pt":"Olá, venho do site da Galeria Contagiarte.","en":"Hello, I came from the Galeria Contagiarte website.","es":"Hola, vengo del sitio de la Galería Contagiarte."}', 'Mensagem já escrita nos botões de WhatsApp que não são de um assunto em particular: o botão flutuante, o rodapé e a página de contactos.', 'geral', 1790244774);
